// Sign-in by popup (PKCE). The popup lands on /auth/callback.html on the platform origin, which posts the code
// back to this frame with the target origin pinned; the frame exchanges it for a session (docs/03-architecture.qmd).
import { exchangeCode, githubSignInUrl, PLATFORM_ORIGIN } from './api.ts'

export function signInWithGitHub(): Promise<void> {
  return new Promise(async (resolve, reject) => {
    let url: string
    try {
      url = await githubSignInUrl()
    } catch (e) {
      return reject(e)
    }
    const w = 600, h = 700
    const left = window.screenX + Math.max(0, (window.outerWidth - w) / 2)
    const top = window.screenY + Math.max(0, (window.outerHeight - h) / 2)
    const popup = window.open(url, 'yrS4-signin', `width=${w},height=${h},left=${left},top=${top},popup=yes`)
    if (!popup) return reject(new Error('The browser blocked the sign-in window. Allow popups for this site and try again.'))
    const onMsg = async (e: MessageEvent) => {
      if (e.origin !== PLATFORM_ORIGIN) return
      const d = e.data as { type?: string; code?: string; error?: string }
      if (!d || d.type !== 'yrS4:auth') return
      window.removeEventListener('message', onMsg)
      clearInterval(poll)
      try {
        if (d.error) throw new Error(d.error)
        if (!d.code) throw new Error('no code came back from the sign-in')
        await exchangeCode(d.code)
        resolve()
      } catch (err) {
        reject(err)
      }
    }
    window.addEventListener('message', onMsg)
    const poll = setInterval(() => {
      if (popup.closed) {
        clearInterval(poll)
        window.removeEventListener('message', onMsg)
        reject(new Error('Sign-in window closed'))
      }
    }, 500)
  })
}
