// The tutor from the frame's side (docs/08-ai-tutor.qmd): instructor-key mode streams from the ai-chat function;
// student-key mode calls Anthropic directly from the browser with the student's own key, which lives only in this
// frame's storage on the platform origin.
import { SUPABASE_URL, getSession } from '../api.ts'
import { firstTurn, pageContextBlock, systemPrompt, type TutorAction, type TutorContext } from '../../../supabase/functions/_shared/tutor-prompt.ts'

export interface TutorRequest {
  package: string
  page: string
  section: string | null
  anchor: unknown
  action: TutorAction
  question?: string
  deep?: boolean
  conversation_id?: string | null
  passage: string | null
  context: { pageTitle: string; headingPath: string[]; sectionText: string; before?: string; after?: string }
}
export interface TutorResult { conversation_id: string | null; cost_usd?: number; model?: string }

export class TutorError extends Error {
  constructor(msg: string, readonly limit?: string, readonly offerStudentKey?: boolean) {
    super(msg)
  }
}

/** Instructor-key mode: the Edge Function streams Server-Sent Events. */
export async function askServer(req: TutorRequest, onDelta: (t: string) => void, signal?: AbortSignal): Promise<TutorResult> {
  const s = await getSession()
  if (!s) throw new TutorError('sign in first')
  const res = await fetch(`${SUPABASE_URL}/functions/v1/ai-chat`, {
    method: 'POST', signal,
    headers: { authorization: `Bearer ${s.access_token}`, 'content-type': 'application/json' },
    body: JSON.stringify(req),
  })
  if (!res.ok) {
    const j = (await res.json().catch(() => ({}))) as { error?: string; limit?: string; offer_student_key?: boolean }
    throw new TutorError(j.error || `tutor error ${res.status}`, j.limit, j.offer_student_key)
  }
  const reader = res.body!.getReader()
  const dec = new TextDecoder()
  let buf = ''
  let result: TutorResult = { conversation_id: req.conversation_id || null }
  for (;;) {
    const { value, done } = await reader.read()
    if (done) break
    buf += dec.decode(value, { stream: true })
    let i: number
    while ((i = buf.indexOf('\n\n')) >= 0) {
      const chunk = buf.slice(0, i)
      buf = buf.slice(i + 2)
      const ev = /^event: (.*)$/m.exec(chunk)?.[1]
      const data = /^data: (.*)$/m.exec(chunk)?.[1]
      if (!ev || !data) continue
      const d = JSON.parse(data)
      if (ev === 'delta') onDelta(d.text)
      else if (ev === 'start') result = { ...result, conversation_id: d.conversation_id, model: d.model }
      else if (ev === 'done') result = { ...result, conversation_id: d.conversation_id, cost_usd: d.cost_usd }
      else if (ev === 'error') throw new TutorError(d.error)
    }
  }
  return result
}

// --- student-key mode -----------------------------------------------------------------------------------------
const KEY = 'yrS4-student-ai-key'
export function getStudentKey(): string | null {
  try {
    return sessionStorage.getItem(KEY) || localStorage.getItem(KEY)
  } catch {
    return null
  }
}
export function setStudentKey(key: string | null, remember: boolean) {
  try {
    sessionStorage.removeItem(KEY)
    localStorage.removeItem(KEY)
    if (key) (remember ? localStorage : sessionStorage).setItem(KEY, key)
  } catch { /* ignore */ }
}

/** Student-key mode: the browser talks to Anthropic directly; nothing goes through yrS4's servers. */
export async function askWithStudentKey(req: TutorRequest, ctx: TutorContext, history: Array<{ role: 'user' | 'assistant'; content: string }>, onDelta: (t: string) => void, signal?: AbortSignal): Promise<TutorResult> {
  const key = getStudentKey()
  if (!key) throw new TutorError('add your Anthropic API key in Settings first')
  const { default: Anthropic } = await import('@anthropic-ai/sdk')
  const client = new Anthropic({ apiKey: key, dangerouslyAllowBrowser: true })
  const model = req.deep ? 'claude-sonnet-5-5' : 'claude-haiku-5-5'
  const userText = history.length ? (req.question || '').trim() : firstTurn(req.action, req.passage, req.question)
  const stream = client.messages.stream({
    model,
    max_tokens: 2000,
    system: [{ type: 'text', text: systemPrompt(ctx), cache_control: { type: 'ephemeral' } }],
    output_config: { effort: 'low' },
    messages: [
      { role: 'user', content: [{ type: 'text', text: pageContextBlock(ctx), cache_control: { type: 'ephemeral' } }, { type: 'text', text: 'Keep this context in mind; the questions follow.' }] },
      { role: 'assistant', content: 'Understood. I have the page context.' },
      ...history,
      { role: 'user', content: userText },
    ],
  }, { signal })
  for await (const event of stream) {
    if (event.type === 'content_block_delta' && event.delta.type === 'text_delta') onDelta(event.delta.text)
  }
  const final = await stream.finalMessage()
  if (final.stop_reason === 'refusal') onDelta('\n\n_(The tutor declined this request.)_')
  return { conversation_id: null, model }
}
