import { store, type State } from '../store.ts'
import type { MarkRow, CoverageStatus } from '../../../shared/types.ts'
import { Md } from './Md.tsx'
import { MarkLabels } from './Labels.tsx'
import { sectionName } from '../../../shared/types.ts'

const STATUS: Record<string, string> = { covered: 'Covered', assigned: 'Read on your own', skipped: 'Skipped' }

export function fmtDate(iso: string | null | undefined): string {
  if (!iso) return ''
  const d = new Date(iso.length === 10 ? iso + 'T12:00:00' : iso)
  return d.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })
}

export function whereText(m: MarkRow): string {
  const a = m.anchor_current || m.anchor
  if (!a) return 'whole book'
  if (a.scope === 'page') return 'whole page'
  if (a.scope === 'section') return `section: ${a.section?.headings.slice(-1)[0] || a.section?.id || ''}`
  return a.quote ? `“${a.quote.exact.slice(0, 90)}${a.quote.exact.length > 90 ? '…' : ''}”` : ''
}

export function PageMarks({ s }: { s: State }) {
  const uid = s.session?.user.id
  const visible = store.visibleMarks()
  const orphan = new Set(s.orphans)
  const canEdit = (m: MarkRow) => !s.viewAsStudent && (m.author_id === uid || (['coverage', 'comment'].includes(m.kind) && m.sections.every((x) => s.staffIds.includes(x.section_id)) && m.sections.length > 0))
  const secName = (id: string) => { const x = s.sections.find((y) => y.id === id); return x ? sectionName(x) : '?' }
  if (!s.pkg) return null
  if (!visible.length) {
    return (
      <div class="muted pad">
        {s.teach && !s.viewAsStudent ? 'Nothing marked on this page for the ticked sections yet. Select text, or hover a heading.' : s.section ? `Nothing marked on this page for ${sectionName(s.section)}.` : (
          <SectionPicker s={s} />
        )}
      </div>
    )
  }
  return (
    <div class="marks">
      {!s.teach && !s.section && <SectionPicker s={s} />}
      {visible.map((m) => (
        <div key={m.id} class={`mark k-${m.kind} ${m.data.status ? 'st-' + m.data.status : ''} ${s.focusMark === m.id ? 'focus' : ''} ${orphan.has(m.id) ? 'orphan' : ''}`}>
          <div class="mark-head">
            <span class="kind">{m.kind === 'label' ? 'Label' : m.kind === 'coverage' ? STATUS[m.data.status as string] || 'Coverage' : m.kind === 'comment' ? 'Comment' : m.kind === 'author_note' ? `Note · ${m.data.category || ''}` : m.kind === 'student_note' ? (m.data.highlight ? 'Highlight' : 'My note') : m.kind === 'message' ? `To instructor · ${m.data.topic || ''}` : m.kind === 'reaction' ? `${m.data.emoji} ${m.data.label}` : m.kind}</span>
            <span class="muted small">
              {m.sections.length ? m.sections.map((x) => `${secName(x.section_id)} ${fmtDate(x.meets_on)}`).join(' · ') : fmtDate(m.created_at)}
            </span>
          </div>
          <button class="link where" onClick={() => store.goto(m.id)} title="Show on the page">{whereText(m)}</button>
          {orphan.has(m.id) && <div class="small warn">Can't find this text on the page any more.</div>}
          {s.reattach[m.id] && (
            <div class="small warn">The text changed; shown at the closest match ({Math.round((s.reattach[m.id].score || 0) * 100)}%).
              {canEdit(m) && <> <button class="small" onClick={() => store.confirmReattach(m)}>Confirm re-attach</button></>}
            </div>
          )}
          {m.kind === 'label' && <MarkLabels s={s} m={m} />}
          {m.body && <div class="body-md"><Md text={m.body} /></div>}
          {(s.replies[m.id] || []).map((r) => <div key={r.id} class="reply small"><strong>{r.author?.display_name || 'reply'}</strong>: <Md text={r.body} /></div>)}
          {canEdit(m) && (
            <div class="actions">
              {m.kind === 'coverage' && (['covered', 'assigned', 'skipped'] as CoverageStatus[]).filter((x) => x !== m.data.status).map((x) => (
                <button key={x} class="small" onClick={() => store.changeStatus(m, x)}>{STATUS[x]}</button>
              ))}
              {(m.kind === 'comment' || m.kind === 'author_note' || (m.kind === 'student_note' && !m.data.highlight)) && <button class="small" onClick={() => store.edit(m)}>Edit</button>}
              {m.kind === 'author_note' && m.status !== 'done' && <button class="small" onClick={() => store.setStatus(m, 'done')}>Done</button>}
              <button class="small danger" onClick={() => { if (confirm('Delete this mark?')) store.remove(m.id) }}>Delete</button>
            </div>
          )}
        </div>
      ))}
    </div>
  )
}

export function SectionPicker({ s }: { s: State }) {
  if (!s.sections.length) return <div class="muted">No section uses this book yet.</div>
  return (
    <div class="card">
      <div>Show coverage for:</div>
      <select value={s.section?.slug || ''} onChange={(e) => store.chooseSection((e.target as HTMLSelectElement).value || null)}>
        <option value="">(off)</option>
        {s.sections.map((x) => <option key={x.id} value={x.slug}>{sectionName(x)} · {x.term}</option>)}
      </select>
      <div class="muted small">Your instructor's link (…?section=…) sets this for you.</div>
    </div>
  )
}
