import { store, type State } from '../store.ts'
import { SectionAiSettings } from './AiSettings.tsx'
import { useState } from 'preact/hooks'
import { sectionName } from '../../../shared/types.ts'
import { LabelChip } from './Labels.tsx'

export function TeachBar({ s }: { s: State }) {
  const mine = s.sections.filter((x) => s.staffIds.includes(x.id))
  const [aiFor, setAiFor] = useState<string | null>(null)
  return (
    <div class={`teachbar ${s.teach ? 'on' : ''}`}>
      <div class="row">
        <label class="switch">
          <input type="checkbox" checked={s.teach} onChange={(e) => store.setTeach((e.target as HTMLInputElement).checked)} />
          <span><strong>Teach</strong> {s.teach ? 'on: select text to label it' : 'off'}</span>
        </label>
        <label class="switch">
          <input type="checkbox" checked={s.viewAsStudent} onChange={(e) => store.setViewAsStudent((e.target as HTMLInputElement).checked)} />
          <span>View as student</span>
        </label>
      </div>
      {s.viewAsStudent && <div class="warn small">Student view: you see what a student of {s.section ? sectionName(s.section) : 'the chosen section'} sees. Switch off to teach.</div>}
      {s.teach && !s.viewAsStudent && (
        <>
          <div class="row">
            <span class="lbl">Sections</span>
            {mine.map((x) => (
              <label key={x.id} class="chk">
                <input type="checkbox" checked={s.teachSections.includes(x.id)} onChange={() => store.toggleTeachSection(x.id)} /> {sectionName(x)}
              </label>
            ))}
          </div>
          <div class="row">
            <span class="lbl">Meeting</span>
            <input type="date" value={s.meetingDate} onChange={(e) => store.setMeetingDate((e.target as HTMLInputElement).value)} />
          </div>
          <div class="row">
            <span class="lbl">Current label</span>
            {s.currentLabel && s.labels.find((l) => l.id === s.currentLabel) ? <LabelChip l={s.labels.find((l) => l.id === s.currentLabel)!} on /> : <span class="muted small">none</span>}
            <button class="link small" onClick={() => store.setView('labels')}>change</button>
            <span class="muted small">select text, press L</span>
          </div>
          <div class="row">
            <span class="lbl">This page</span>
            <button class="small" disabled={s.busy || !s.currentLabel} onClick={() => store.labelWholePage()}>Apply current label</button>
            <button class="small" disabled={s.busy} onClick={() => store.noteOnPage()}>Private note</button>
          </div>
          <div class="row">
            <span class="lbl">Join codes</span>
            {mine.map((x) => (
              <span key={x.id} class="small">{sectionName(x)}: <code>{s.joinCodes[x.id] || '—'}</code> <button class="link small" onClick={() => store.setJoinCode(x.id, Math.random().toString(36).slice(2, 8))}>{s.joinCodes[x.id] ? 'new' : 'make'}</button></span>
            ))}
          </div>
          <div class="row">
            <label class="chk"><input type="checkbox" checked={s.showNotes} onChange={(e) => store.setShowNotes((e.target as HTMLInputElement).checked)} /> Show my private notes on the page</label>
            <label class="chk"><input type="checkbox" checked={s.showActivity} onChange={(e) => store.setShowActivity((e.target as HTMLInputElement).checked)} /> Show class activity</label>
          </div>
          <div class="row">
            <span class="lbl">Tutor</span>
            {mine.map((x) => <button key={x.id} class="small" onClick={() => setAiFor(aiFor === x.id ? null : x.id)}>{sectionName(x)}: {((x.ai as { mode?: string })?.mode) || 'off'}</button>)}
          </div>
          {aiFor && mine.find((x) => x.id === aiFor) && <SectionAiSettings s={s} section={mine.find((x) => x.id === aiFor)!} />}
          {!s.teachSections.length && <div class="warn small">Tick at least one section so coverage labels count for it.</div>}
          <div class="muted small">Projector tip: close this panel (or press \) to hide everything but the students' view.</div>
        </>
      )}
    </div>
  )
}
